import{_ as r,C as t,o,c as i,E as n,a2 as l}from"./chunks/framework.Cm6XCzck.js";const _=JSON.parse('{"title":"模型路由必须在政策边界内优化，而不是取代政策","description":"","frontmatter":{"title":"模型路由必须在政策边界内优化，而不是取代政策","date":"2026-08-05","column":"industry-architecture","category":"daily","summary":"只有当资格、权限、回退与审计都被明确并持久化，自动模型选择才构成企业级架构。","item_id":"Q-20260805-13","source_research_object":"research/analysis/Q-20260805-13-governed-model-routing.md","source_reading_result":"research/reading/Q-20260805-13-governed-model-routing.md","lifecycle":"Published","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep","cover":"/assets/covers/daily-2026-08-05-governed-model-routing-cover-v2.jpg"},"headers":[],"relativePath":"zh/industry/2026-08-05-governed-model-routing.md","filePath":"zh/industry/2026-08-05-governed-model-routing.md","lastUpdated":1787407830000}'),d={name:"zh/industry/2026-08-05-governed-model-routing.md"};function s(c,e,u,h,m,g){const a=t("ArticleCover");return o(),i("div",null,[n(a,{image:"/assets/covers/daily-2026-08-05-governed-model-routing-cover-v2.jpg",kicker:"行业架构 · 每日研究",title:"模型路由必须在政策边界内优化，而不是取代政策",summary:"只有当资格、权限、回退与审计都被明确并持久化，自动模型选择才构成企业级架构。",version:"Q-20260805-13",status:"Daily Runtime V5 · 2026-08-05",languageHref:"/en/industry/2026-08-05-governed-model-routing",languageLabel:"English"}),e[0]||(e[0]=l('<h1 id="模型路由必须在政策边界内优化-而不是取代政策" tabindex="-1">模型路由必须在政策边界内优化，而不是取代政策 <a class="header-anchor" href="#模型路由必须在政策边界内优化-而不是取代政策" aria-label="Permalink to &quot;模型路由必须在政策边界内优化，而不是取代政策&quot;">​</a></h1><p>只有当资格、权限、回退与审计都被明确并持久化，自动模型选择才构成企业级架构。</p><h2 id="核心判断" tabindex="-1">核心判断 <a class="header-anchor" href="#核心判断" aria-label="Permalink to &quot;核心判断&quot;">​</a></h2><p>路由是服从版本化政策决定的优化服务，不是权限来源。</p><h2 id="为什么这不是一个单点功能" tabindex="-1">为什么这不是一个单点功能 <a class="header-anchor" href="#为什么这不是一个单点功能" aria-label="Permalink to &quot;为什么这不是一个单点功能&quot;">​</a></h2><p>路由器可以按任务类型与复杂度分类，并针对智能、平衡或成本优化；企业政策回答的是另一类问题：哪些供应商、模型、数据类别、预算、区域和能力具备资格。两者合并后，不透明优化器可能悄然重写治理边界。</p><h2 id="可落地的最小架构" tabindex="-1">可落地的最小架构 <a class="header-anchor" href="#可落地的最小架构" aria-label="Permalink to &quot;可落地的最小架构&quot;">​</a></h2><p>每次调用都应持久化 Route Decision Envelope：政策版本、任务分类、合格与被排除候选、所选模型及版本、优化目标、成本或延迟估计、回退或异常原因、披露模式。优先级、空候选池、故障回退和退役迁移必须在分类器之外定义。</p><h2 id="边界与反证" tabindex="-1">边界与反证 <a class="header-anchor" href="#边界与反证" aria-label="Permalink to &quot;边界与反证&quot;">​</a></h2><p>公开材料没有披露分类置信度、阈值、候选集构造、路由错误率或可复现的节省评估；模型退役时，路由也不会消除配置迁移义务。</p><h2 id="工程结论" tabindex="-1">工程结论 <a class="header-anchor" href="#工程结论" aria-label="Permalink to &quot;工程结论&quot;">​</a></h2><p>分离 Policy、Routing、Execution 与 Audit 四个平面。合格候选为空时应失败关闭或升级处理，绝不能为了满足优化器而静默放宽政策。</p><h2 id="可视化说明" tabindex="-1">可视化说明 <a class="header-anchor" href="#可视化说明" aria-label="Permalink to &quot;可视化说明&quot;">​</a></h2><p>配图用于表达控制边界和状态关系，不表达实验结果，也不制造原始研究对象未支持的量化比较。</p><h2 id="证据与引用" tabindex="-1">证据与引用 <a class="header-anchor" href="#证据与引用" aria-label="Permalink to &quot;证据与引用&quot;">​</a></h2><ol><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/analysis/Q-20260805-13-governed-model-routing.md" target="_blank" rel="noreferrer">Research Object</a>：本文唯一分析输入，包含研究判断、不确定性、反证和工程影响。</li><li><a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/reading/Q-20260805-13-governed-model-routing.md" target="_blank" rel="noreferrer">Reading Result</a>：Research Object 的证据边界与来源追溯记录。</li></ol>',16))])}const b=r(d,[["render",s]]);export{_ as __pageData,b as default};
